int msbIndex128(uint128 x) {
    if (x == 0) return -1; // illustrative; actual solution avoids branches
    int idx = 0;
    if (x >> 64) { x >>= 64; idx += 64; }
    if (x >> 32) { x >>= 32; idx += 32; }
    if (x >> 16) { x >>= 16; idx += 16; }
    if (x >> 8)  { x >>= 8;  idx += 8; }
    if (x >> 4)  { x >>= 4;  idx += 4; }
    if (x >> 2)  { x >>= 2;  idx += 2; }
    if (x >> 1)  { idx += 1; }
    return idx;
}
```

